section.sourcecode:
type amm:uint;
 typedef constrained-uint {
   description
     "constrained number";
   units "meter";
   type amm:uint {
     range "3..10";
   }
 }
 typedef constrained-textstr {
   description
     "constrained text size";
   type amm:textstr {
     length "10..100";
   }
 }

amm:ulist {
  type amm:uint;
}
amm:ulist {
  type amm:uint {
    range "3..10";
  }
  min-elements 2;
  max-elements 10;
}

amm:dlist {
  // each "type" substatement is one element of the AC
  type amm:uint;
  type amm:uint;
}
amm:dlist {
  // first AC element is text
  type amm:textstr;
  // remaining 2-10 element are int
  amm:seq {
    type amm:int;
    min-elements 2;
    max-elements 10;
  }
}

amm:umap {
  description
    "restrict only keys";
  amm:keys {
    type amm:uint;
  }
}
amm:umap {
  description
    "Map uint to text values.";
  amm:keys {
    type amm:uint;
  }
  amm:values {
    type amm:textstr;
  }
}

amm:tblt {
  amm:column first {
    type amm:uint;
  }
  amm:column second {
    type amm:textstr;
  }
  amm:key "first";
}

union {
  type amm:int;
  type amm:textstr;
}
union {
  type amm:uint {
    range "3..10";
  }
  type amm:textstr;
}

amm:dlist {
  type amm:textstr;
  amm:seq {
    type amm:uint;
    min-elements 1;
  }
}

amm:parameter first {
  type amm:uint {
    range "3..10";
  }
}
amm:parameter second {
  type amm:textstr;
  amm:default "\"value\"";
}
amm:parameter third {
  amm:ulist {
    type amm:uint;
  }
  amm:default "/AC/(3,5,8)"
}

typedef restricted-uint {
  description
    "Example restriction";
  type amm:uint {
    range "3..10";
  }
}
typedef annotated-uint {
  description
    "Example units annotation";
  type amm:uint;
  units "meter";
}
typedef structured-ac {
  description
    "Example units on AC items";
  units "meter";
  amm:ulist {
    type amm:real32;
    min-elements 3;
    max-elements 10;
  }
}

amm:ident base-a {
  amm:abstract true;
  description
    "A base identity object.";
}
amm:ident base-b {
  amm:abstract true;
  description
    "Another base identity object.";
}
amm:ident use-1 {
  amm:base "./IDENT/base-a";
  description
    "An identity derived from base-a.";
}
amm:ident use-2 {
  amm:base "./IDENT/use-1";
  amm:base "./IDENT/base-b";
  description
    "An identity derived from base-a (via use-1) and base-b.";
}
amm:ident use-3 {
  amm:base "./IDENT/base-b";
  amm:parameter option {
    type amm:int;
  }
  description
    "An identity derived from base-b which includes a parameter.";
}

amm:const pi32 {
  type amm:real32;
  amm:init-value "3.14159";
  description
    "A truncated value of Pi.";
}

amm:const do_thing {
  type amm-base:mac;
  amm:init-value "/AC/(../CTRL/first,../CTRL/second(2))";
  description
    "Execute two controls in sequence.";
}

amm:ctrl reset_count {
  amm:parameter src {
    type amm:textstr;
    description
      "The name of the source.";
  }
  amm:result previous {
    type amm:uvast;
    description
      "The value just before reset.";
  }
  description
    "This control resets counts for the given source.";
}

leaf tx_count {
  config false;
  type amm-base:counter64;
  units "frames";
  description
    "The count of the number of frames sent.";
}

amm:oper add {
  amm:operand val-a {
    type amm-base:numeric;
  }
  amm:operand val-b {
    type amm-base:numeric;
  }
  amm:result sum {
    type amm-base:numeric;
  }
  description
    "Sum together the two operands.";
}

amm:oper sum {
  description
    "Sum together a sequence from the stack.";
  amm:parameter count {
    description
      "The number of operands to pop."
    type amm:uint {
      range "1..max";
    }
  }
  amm:operand value {
    description
      "This is not within a container, so does not represent an AC;
      it is multiple operands.";
    type amm-base:numeric;
  }
  amm:result sum {
    type amm-base:numeric;
  }
}

amm:sbr enable_safe_mode {
  description
    "Enable safe mode below threshold.";
  amm:action "/AC/(./CTRL/ensure_safe_mode(true))";
  amm:condition "/AC/(./EDD/sensor,./VAR/min_threshold,"
    +"/ietf-amm/OPER/compare_lt)";
}

amm:tbr tlm_rule {
  description
    "Generate telemetry reports.";
  amm:action "/AC/(./CTRL/first,/adm2/CTRL/other)";
  amm:period "/TD/PT30s";
}

amm:var min_threshold {
  description
    "The lower threshold to enable safe mode.";
  type amm:real32;
  amm:init-value "1e4";
}
